package io.rift.cronos;
import java.util.*;import java.math.BigInteger;
public final class DiscoveryPolicyHarness {
 static int count;interface Op{void run()throws Exception;}static void ok(boolean v){count++;if(!v)throw new AssertionError("check "+count);}static void bad(Op op)throws Exception{try{op.run();}catch(Exception e){count++;return;}throw new AssertionError("unexpected acceptance");}
 static String w(BigInteger n){return String.format("%064x",n);}static String w(long n){return w(BigInteger.valueOf(n));}
 public static void main(String[] ignored)throws Exception{String owner="0x"+"a".repeat(40),other="0x"+"b".repeat(40),ot=DiscoveryPolicy.ownerTopic(owner),xt=DiscoveryPolicy.ownerTopic(other),max=w(BigInteger.ONE.shiftLeft(256).subtract(BigInteger.ONE));ok(DiscoveryPolicy.block("0")==0);ok(DiscoveryPolicy.block("9007199254740991")==9007199254740991L);for(String s:new String[]{"-1","01","0x1","9007199254740992","9999999999999999","recent"})bad(()->DiscoveryPolicy.block(s));for(String s:new String[]{"0","2001","-1","01","10000"})bad(()->DiscoveryPolicy.span(s));ok(DiscoveryPolicy.span("2000")==2000);
 List<String> nft=Arrays.asList(DiscoveryPolicy.TRANSFER,xt,ot,"0x"+max);ok(DiscoveryPolicy.tokens("ERC-721",owner,true,nft,"0x").get(0).equals(new BigInteger(max,16).toString()));bad(()->DiscoveryPolicy.tokens("ERC-721",owner,false,nft,"0x"));ok(DiscoveryPolicy.tokens("ERC-721",owner,true,Arrays.asList(DiscoveryPolicy.TRANSFER,xt,ot),"0x"+w(1)).isEmpty());bad(()->DiscoveryPolicy.tokens("ERC-721",owner,true,nft,"0x"+w(1)));bad(()->DiscoveryPolicy.tokens("ERC-721",owner,true,Arrays.asList(DiscoveryPolicy.TRANSFER,"0x"+"1".repeat(64),ot,"0x"+w(1)),"0x"));
 List<String> single=Arrays.asList(DiscoveryPolicy.SINGLE,xt,xt,ot);ok(DiscoveryPolicy.tokens("ERC-1155",owner,true,single,"0x"+max+w(3)).size()==1);ok(DiscoveryPolicy.tokens("ERC-1155",owner,true,single,"0x"+w(1)+w(0)).isEmpty());bad(()->DiscoveryPolicy.tokens("ERC-1155",owner,true,single,"0x"+w(1)));
 List<String> batch=Arrays.asList(DiscoveryPolicy.BATCH,xt,xt,ot);String data="0x"+w(64)+w(160)+w(2)+w(7)+max+w(2)+w(0)+w(9);List<String> ids=DiscoveryPolicy.tokens("ERC-1155",owner,true,batch,data);ok(ids.size()==1&&ids.get(0).equals(new BigInteger(max,16).toString()));ok(DiscoveryPolicy.tokens("ERC-1155",owner,true,batch,"0x"+w(64)+w(96)+w(0)+w(0)).isEmpty());for(String value:new String[]{data+"00",data.substring(0,data.length()-64),"0x"+w(64)+w(160)+w(129)+data.substring(194),"0x"+w(32)+data.substring(66),"0x"+w(64)+w(192)+data.substring(130)})bad(()->DiscoveryPolicy.tokens("ERC-1155",owner,true,batch,value));bad(()->DiscoveryPolicy.tokens("ERC-1155",owner,true,batch,"0x"+"a".repeat(16642)));bad(()->DiscoveryPolicy.tokens("ERC-20",owner,true,nft,"0x"));
 System.out.println("Discovery policy checks passed: "+count+"; no live provider/device acceptance");}
}
